package com.lamggm.rospocket;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
/** Pure Java forces, no fake clock/network/Android model. */
public class GraphPhysicsTest {
 static Map<String,double[]> seeds(double...xy){Map<String,double[]> m=new LinkedHashMap<>();for(int i=0;i<xy.length;i+=2)m.put("n"+(i/2),new double[]{xy[i],xy[i+1]});return m;}
 static double distance(GraphPhysics p){GraphPhysics.Body a=p.bodies.get("n0"),b=p.bodies.get("n1");return Math.hypot(a.x-b.x,a.y-b.y);}
 @Test public void namespaceEnvelopesRepelWithoutMovingAPinnedMember(){GraphPhysics p=new GraphPhysics();p.centering=0;p.sync(seeds(-70,0,70,0,-70,0,70,0),Collections.emptyList());Map<String,String> groups=new LinkedHashMap<>();groups.put("n0","/a");groups.put("n1","/a");groups.put("n2","/b");groups.put("n3","/b");p.setNamespaces(groups);p.pin("n0",true);for(int i=0;i<120;i++)p.step();Map<String,GraphNamespaces.Circle> circles=p.namespaceCircles();GraphNamespaces.Circle a=circles.get("/a"),b=circles.get("/b");assertTrue("Repel the full namespace envelopes, not only their dots",Math.hypot(a.x-b.x,a.y-b.y)>=a.r+b.r+39);assertEquals(-70,p.bodies.get("n0").x,0);assertEquals(0,p.bodies.get("n0").y,0);while(p.awake)p.step();p.setNamespaces(groups);assertFalse("Same namespace metadata must not reheat",p.awake);p.clear();assertTrue(p.namespaces.isEmpty());}
 @Test public void namespaceCohesionPullsOnlyItsOwnMembers(){GraphPhysics p=new GraphPhysics();p.centering=0;p.repulsion=0;p.sync(seeds(-1000,0,1000,0,4000,0),Collections.emptyList());Map<String,String> groups=new LinkedHashMap<>();groups.put("n0","/robo/nav");groups.put("n1","/robo/nav");p.setNamespaces(groups);double before=distance(p);for(int i=0;i<30;i++)p.step();assertTrue("A namespace needs real cohesion, not only a drawn circle",distance(p)<before-100);assertEquals(4000,p.bodies.get("n2").x,0);}
 @Test public void springPullsConnectedDistantBodiesTogether(){GraphPhysics p=new GraphPhysics();p.centering=0;p.repulsion=0;p.sync(seeds(0,0,1200,0),Collections.singletonList(new String[]{"n0","n1"}));double d=distance(p);for(int i=0;i<30;i++)p.step();assertTrue(distance(p)<d-100);}
 @Test public void repulsionSeparatesUnconnectedBodies(){GraphPhysics p=new GraphPhysics();p.centering=0;p.repulsion=5;p.sync(seeds(-400,0,400,0),Collections.emptyList());double d=distance(p);for(int i=0;i<30;i++)p.step();assertTrue(distance(p)>d);}
 @Test public void coincidentRectanglesSeparateAndSettleInBoundedWork(){GraphPhysics p=new GraphPhysics();p.centering=0;p.repulsion=0;p.sync(seeds(0,0,0,0),Collections.emptyList());int n=0;while(p.awake&&n++<500)p.step();assertFalse(p.awake);assertTrue(n<=GraphPhysics.MAX_STEPS);GraphPhysics.Body a=p.bodies.get("n0"),b=p.bodies.get("n1");assertTrue(Math.abs(a.x-b.x)>280||Math.abs(a.y-b.y)>85);assertTrue(Double.isFinite(a.x)&&Double.isFinite(a.y));}
 @Test public void fixedAndHeldBodiesStayPutWhileTheirNeighborsMove(){GraphPhysics p=new GraphPhysics();p.sync(seeds(0,0,1000,0),Collections.singletonList(new String[]{"n0","n1"}));p.pin("n0",true);p.hold("n1",true);for(int i=0;i<20;i++)p.step();assertEquals(0,p.bodies.get("n0").x,0);assertEquals(1000,p.bodies.get("n1").x,0);p.hold("n1",false);p.wake();for(int i=0;i<20;i++)p.step();assertEquals(0,p.bodies.get("n0").x,0);assertNotEquals(1000,p.bodies.get("n1").x,0);}
 @Test public void repeatedSnapshotsDoNotWakeASettledSceneOrReplaceBodies(){GraphPhysics p=new GraphPhysics();Map<String,double[]> s=seeds(0,0,1000,0);p.sync(s,Collections.emptyList());while(p.awake)p.step();GraphPhysics.Body a=p.bodies.get("n0");double x=a.x;p.sync(s,Collections.emptyList());assertSame(a,p.bodies.get("n0"));assertFalse(p.awake);assertEquals(x,a.x,0);s.put("n2",new double[]{20,40});p.sync(s,Collections.emptyList());assertSame(a,p.bodies.get("n0"));assertEquals(x,a.x,0);assertTrue(p.awake);}
 @Test public void disablingPhysicsPreservesCoordinatesAndClearRetiresPins(){GraphPhysics p=new GraphPhysics();p.sync(seeds(0,0,1000,0),Collections.emptyList());p.pin("n0",true);p.enabled=false;double x=p.bodies.get("n1").x;for(int i=0;i<50;i++)assertFalse(p.step());assertEquals(x,p.bodies.get("n1").x,0);p.clear();assertTrue(p.bodies.isEmpty());assertFalse(p.awake);}
 @Test public void nodeCountAndMotionAreBoundedAtTheNativeSceneLimit(){Map<String,double[]> s=new LinkedHashMap<>();for(int i=0;i<300;i++)s.put("n"+i,new double[]{i,0});GraphPhysics p=new GraphPhysics();p.sync(s,Collections.emptyList());assertEquals(160,p.bodies.size());for(int i=0;i<400;i++)p.step();assertFalse(p.awake);for(GraphPhysics.Body b:p.bodies.values()){assertTrue(Double.isFinite(b.x)&&Double.isFinite(b.y));assertTrue(Math.abs(b.x)<=100000&&Math.abs(b.y)<=100000);}}
}
